using UnityEngine;using UnityEngine.AI;using System.Collections;using System.IO;using System.Linq;
public class VillagerCandidateProbe:MonoBehaviour {
 public bool review;
 IEnumerator Start(){string e="Evidence/villager-candidate-20261030/";yield return new WaitForSeconds(1);if(review){var cam=Camera.main;var a=GetComponent<Animator>();for(int i=0;i<3;i++){cam.transform.position=Quaternion.Euler(0,i*90,0)*new Vector3(0,1.15f,3.8f);cam.transform.LookAt(Vector3.up*1.05f);yield return new WaitForSeconds(.5f);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"npc_"+i+".png"));yield return new WaitForSeconds(.2f);}File.WriteAllText(e+"npc-playmode.txt","Avatar valid="+a.avatar.isValid+" human="+a.isHuman+" state="+a.GetCurrentAnimatorStateInfo(0).shortNameHash+" normalizedTime="+a.GetCurrentAnimatorStateInfo(0).normalizedTime+" activeSkinned="+GetComponentsInChildren<SkinnedMeshRenderer>().Length+" nullBones="+GetComponentsInChildren<SkinnedMeshRenderer>().Sum(r=>r.bones.Count(b=>!b))+"\n");yield break;}
 var player=FindObjectOfType<HunterTorchPose>();var m=player.GetComponent<DemoMovement>();var camWorld=m.viewCamera;var follow=camWorld.GetComponent<DemoCamera>();var agent=player.GetComponent<NavMeshAgent>();var pit=GameObject.Find("Village fire pit").transform;NavMesh.SamplePosition(pit.position+new Vector3(2,0,-2),out var p,5,NavMesh.AllAreas);agent.Warp(p.position);yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"bonfire.png"));yield return new WaitForSeconds(.3f);NavMesh.SamplePosition(transform.position+new Vector3(0,0,-2),out p,5,NavMesh.AllAreas);agent.Warp(p.position);yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"npc_world.png"));yield return new WaitForSeconds(.3f);var clue=GetComponent<DemoInteractable>();m.BeginInteraction(clue);yield return new WaitForSeconds(1.3f);var light=player.GetComponentsInChildren<Light>().First(l=>l.name=="Carried lantern");File.WriteAllText(e+"world-playmode.txt","BonfirePlaying="+pit.GetComponentsInChildren<ParticleSystem>().Count(ps=>ps.isPlaying)+" torchIntensity="+light.intensity+" range="+light.range+" witnessRecorded="+player.GetComponent<DemoInvestigation>().HasWitness+"\n");}
}
